import{cultureCounts,berryOutput}from './bound-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17,c='#f8f4ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const path=(d,c='#b7cac5',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const box=(x,y,w,h,c='#304e5e')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="${c}" stroke="#a6beb8"/>`;
export const boundSVG=(a,label)=>`<svg viewBox="0 0 560 420" role="img" aria-label="${esc(label)}">${a}</svg>`;
export function cultureFigure({treatment='yes',stage=0}={}){let c=cultureCounts(treatment,stage),a=tx(280,28,'Count variants before and after selection',22)+tx(280,64,'Antibiotic: '+(treatment==='yes'?'present':'absent')+' · stage '+stage,17);for(let i=0;i<c.total;i++){let resistant=i>=c.susceptible,x=70+i%10*46,y=110+Math.floor(i/10)*44;a+=`<circle cx="${x}" cy="${y}" r="14" fill="${resistant?'#edab93':'#bdd0c3'}" stroke="#f8eee0"/>`+tx(x,y+5,resistant?'R':'S',12,'#183449');}a+=tx(280,314,'S: '+c.susceptible+' · R: '+c.resistant+' · total: '+c.total,20)+tx(280,348,'Resistant: '+c.percent+'%',20)+tx(280,383,stage===0?'Variants already present':stage===1?'Exposure changes survival, not survivor count':'One division increases survivor numbers',15)+tx(280,410,'Toy cohort · no new mutations shown · not clinical rates',13);return boundSVG(a,'Illustrative culture: antibiotic '+treatment+', stage'+stage+', susceptible'+c.susceptible+', resistant'+c.resistant+', total'+c.total+', resistant percentage'+c.percent+'. Letters supplement colour.');}
export function resistanceFilm(p){let phase=Math.min(3,Math.floor(Math.max(0,Math.min(1,p))*4));return cultureFigure({treatment:'yes',stage:Math.min(2,phase)});}
export function communityFigure({progress=0,water='wet',pollinators='yes',revealed=false}={}){let p=Math.max(0,Math.min(1,progress)),a=tx(280,28,'Follow services through a small community',21);let nodes=[[95,130,'Pollinator'],[275,230,'Flowering plant'],[465,130,'Fruit consumer'],[275,75,'Shelter plant']];a+=path('M125 150L245 210')+path('M310 210L435 150')+path('M435 170Q440 330 310 260','#9bafbd',2)+path('M310 75L440 110','#9bafbd',2);a+=path('M235 200l10 10 -15 0')+path('M421 152l14 -2 -5 13')+path('M323 258l-13 2 6 12');for(let[x,y,label]of nodes){a+=`<circle cx="${x}" cy="${y}" r="32" fill="${label==='Pollinator'?'#dfb688':label==='Fruit consumer'?'#a3bac8':'#8fac99'}" stroke="#f2e0c4" stroke-width="2"/>`;a+=label.includes('plant')?path(`M${x} ${y+14}v-27m0 12q-20 -20 -17 -5m17 0q20 -20 17 -5`,'#183f39',3):label==='Pollinator'?`<ellipse cx="${x}" cy="${y}" rx="17" ry="10" fill="#183f39"/><ellipse cx="${x-5}" cy="${y-12}" rx="9" ry="6" fill="#f8f0e3"/>`:`<path d="M${x-20} ${y+6}q5 -30 29 -9l14 2 -13 6q-9 19 -30 1" fill="#183f39"/>`;a+=tx(x,y+54,label,15);}a+=tx(172,215,'pollination',13)+tx(392,202,'fruit',13)+tx(280,320,'seeds and other dependencies',14);if(progress>0){let segment=Math.floor(p*3),q=p*3-segment,from=[[125,150],[310,210],[435,170]][Math.min(2,segment)],to=[[245,210],[435,150],[310,260]][Math.min(2,segment)];a+=`<circle cx="${from[0]+(to[0]-from[0])*q}" cy="${from[1]+(to[1]-from[1])*q}" r="8" fill="#f38d75"/>`;}a+=tx(280,363,'Water: '+(water==='wet'?'adequate':'dry')+' · pollinators: '+(pollinators==='yes'?'present':'absent'),16)+tx(280,391,revealed?'Toy berry output: '+berryOutput(water,pollinators)+' units':'Predict, then run the controlled model',17)+tx(280,414,'A few dependencies only · original model, not field measurements',12);return boundSVG(a,'Small community dependency model. Pollinator supports flowering plant; fruit supports consumer; other shelter/seed dependencies exist. Water '+water+', pollinator '+pollinators+(revealed?', toy output '+berryOutput(water,pollinators):', output not yet revealed')+'. Signals represent services, not population rates.');}
export function extinctionFigure(){let a=tx(280,30,'Local loss is not global extinction',22)+path('M65 85V330H505');let data=[[20,12],[9,3],[5,0],[0,0]],xs=[90,215,340,475];for(let i=0;i<4;i++){let x=xs[i];for(let[j,col]of['#f0b38e','#a9c6b6'].entries()){let y=330-data[i][j]*10;a+=`<circle cx="${x}" cy="${y}" r="6" fill="${col}"/>`;if(i<3)a+=path(`M${x} ${y}L${xs[i+1]} ${330-data[i+1][j]*10}`,col,i===2?1:3);}a+=tx(x,354,['First','Second','Third','Possible later'][i],13);}for(let n of[0,5,10,15,20])a+=tx(42,335-n*10,n,12);a+=tx(280,72,'Living individuals · fictional counts',16)+tx(280,386,'Peach: global total · green: island',16)+tx(280,411,'Third survey:5 mainland survivors · later zero is hypothetical',13);return boundSVG(a,'Fictional global totals20,9,5 and hypothetical0; island counts12,3,0,0. At third survey species survives on mainland. Only zero global survivors means extinction. Not a forecast.');}
export function rankFigure(progress=0){let ranks=['Kingdom','Phylum','Class','Order','Family','Genus','Species'],a=tx(280,30,'Broad → narrow: nested classification',23);for(let[i,s]of ranks.entries()){let w=450-i*45,x=280-w/2,y=64+i*43;a+=box(x,y,w,35,i<Math.round(progress*7)?'#6b5c55':'#304e5e')+tx(280,y+24,s,17);}return boundSVG(a+tx(280,410,'Binomial name: genus + species · domain is a broader model',13),'Traditional Linnaean ranks broad to narrow: kingdom, phylum, class, order, family, genus, species.');}
export function treeFigure(){let a=tx(280,30,'Trace shared branching points',23)+path('M85 340V95H465M85 240H275V185H465M275 240V300H465');a+=tx(75,370,'R',17)+tx(260,265,'S',17)+tx(495,100,'X',20)+tx(495,190,'Y',20)+tx(495,305,'Z',20)+tx(280,395,'Y/Z share S · modern tips are not direct ancestors',16);return boundSVG(a,'Tree R splits to X and S; S splits to Y/Z. Y and Z share the more recent common ancestor S. Rotating branches leaves the relationships unchanged.');}
export function temperatureFigure(){let a=tx(280,28,'Original supplied temperature response',22)+tx(280,66,'Mean plants per plot · matched stated conditions',16)+path('M75 90V320H500');for(let[i,v]of[6,14,9].entries()){let x=145+i*135;a+=`<rect x="${x-30}" y="${320-v*13}" width="60" height="${v*13}" rx="6" fill="#a9c6b6"/>`+tx(x,305-v*13,v,17)+tx(x,350,[10,20,30][i]+'°C',17);}for(let n of[0,5,10,15])a+=tx(48,325-n*13,n,13);return boundSVG(a+tx(280,388,'Best tested condition ≠ exact optimum at every temperature',14)+tx(280,411,'Fictional data · do not extrapolate to all species',13),'Fictional mean plants per plot at10°C=6,20°C=14,30°C=9. Highest supplied count at20°C, not a universal or exact optimum.');}
const evidence={
'extinction-factors':['Habitat/environment change; resource loss','New predators, pathogens or competition','Catastrophes and combined pressures'],
'extinction-evidence':['Local absence ≠ global extinction','Decline may have several interacting causes','Use evidence, comparisons and uncertainty'],
stewardship:['Appropriate prescribing; use as directed','Restrict agricultural antibiotic use','MRSA: some resistance ≠ every treatment fails'],
binomial:['Homo sapiens = genus + species','Genus capital; species lower case','Scientific print normally uses italics'],
domains:['Archaea · Bacteria · Eukaryota','Eukaryota: protists, fungi, plants, animals','New internal/chemical evidence revised models'],
levels:['Individual → population → community','Ecosystem = community + abiotic interactions','Population: one species in an area'],
competition:['Plants: light, space, water, mineral ions','Animals: food, mates, territory','Infer useful features from the habitat context'],
'community-evidence':['Food, shelter, pollination, seed dispersal','Removing a link may affect other species','Stability allows fluctuations around a balance'],
'abiotic-factors':['Light, temperature, moisture, pH, minerals','Wind intensity/direction; carbon dioxide for plants','Dissolved oxygen for aquatic animals'],
'moisture-data':['Dry plots:4,6,5 → mean5 plants per plot','Moist plots:11,13,12 → mean12 plants per plot','Repeated values show variation within groups'],
'abiotic-evidence':['Light/CO₂ → photosynthesis','Dissolved oxygen → aquatic respiration','Correlation alone does not prove a sole cause']};
export function boundFigure(o={}){if(o.concealed)return boundSVG(tx(280,210,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(o.kind==='resistance')return resistanceFilm(o.progress??0);if(o.kind==='culture-data')return cultureFigure(o);if(o.kind==='community-process'||o.kind==='community-data')return communityFigure(o);if(o.kind==='extinction')return extinctionFigure();if(o.kind==='ranks')return rankFigure(o.progress??0);if(o.kind==='tree')return treeFigure();if(o.kind==='temperature-data')return temperatureFigure();let rows=evidence[o.kind]||evidence.levels;return boundSVG(tx(280,35,'Inspect the supplied evidence',22)+rows.map((s,i)=>tx(280,130+i*85,s,17)).join('')+tx(280,410,'Original educational comparison · use the stated context',13),'Evidence comparison. '+rows.join('. '));}
